{
  "analysis": "Dense frames at 2 fps are available (380 frames). OCR on samples shows the terminal text and prompt lines are readable, including typed commands with a cursor underscore. To reconstruct all player moves, I need OCR every dense frame and save the text with frame markers for systematic parsing.",
  "plan": "Run a shell loop over all dense frames, OCR each with Tesseract, and write frame-marked text to /app/dense_ocr.txt. This may take up to a minute or more; if it is still running, I will poll afterward.",
  "commands": [
    {
      "keystrokes": "for f in /app/dense/frame_*.png; do echo \"=== $(basename \"$f\") ===\"; tesseract \"$f\" stdout --psm 6 2>/dev/null; echo; done > /app/dense_ocr.txt\n",
      "duration": 60.0
    }
  ]
}
